const DROP = ['script','style','svg','nav','footer','header','noscript','iframe','form','button'];
function dropBlocks(html) {
  let s = String(html || '');
  for (let i = 0; i < DROP.length; i++) {
    const t = DROP[i];
    s = s.replace(new RegExp('<' + t + '\\b[\\s\\S]*?<\\/' + t + '>', 'gi'), '');
    s = s.replace(new RegExp('<' + t + '\\b[^>]*\\/?>', 'gi'), '');
  }
  return s;
}
function htmlToMd(html) {
  let s = dropBlocks(html);
  s = s.replace(/<br\s*\/?>/gi, '\n');
  s = s.replace(/<\/p>/gi, '\n\n');
  s = s.replace(/<\/div>/gi, '\n');
  s = s.replace(/<\/li>/gi, '\n');
  s = s.replace(/<h1[^>]*>/gi, '\n# ');
  s = s.replace(/<\/h1>/gi, '\n');
  s = s.replace(/<h2[^>]*>/gi, '\n## ');
  s = s.replace(/<\/h2>/gi, '\n');
  s = s.replace(/<h3[^>]*>/gi, '\n### ');
  s = s.replace(/<\/h3>/gi, '\n');
  s = s.replace(/<(strong|b)[^>]*>/gi, '**');
  s = s.replace(/<\/(strong|b)>/gi, '**');
  s = s.replace(/<(em|i)[^>]*>/gi, '*');
  s = s.replace(/<\/(em|i)>/gi, '*');
  s = s.replace(/<li[^>]*>/gi, '- ');
  s = s.replace(/<[^>]+>/g, '');
  s = s.replace(/&nbsp;/g, ' ');
  s = s.replace(/&amp;/g, '&');
  s = s.replace(/&lt;/g, '<');
  s = s.replace(/&gt;/g, '>');
  s = s.replace(/&quot;/g, '"');
  s = s.replace(/&#39;/g, "'");
  s = s.replace(/[ \t]+\n/g, '\n');
  s = s.replace(/\n{3,}/g, '\n\n');
  return s.trim();
}
const j = $input.item.json;
return { json: { url: j.url || '', clean_md: htmlToMd(j.html || j.content || '') } };

function blockText(j) {
  if (!j) return '';
  if (typeof j.content === 'string') return j.content;
  if (typeof j.textContent === 'string') return j.textContent;
  if (typeof j.plain_text === 'string') return j.plain_text;
  const keys = ['paragraph','heading_1','heading_2','heading_3','bulleted_list_item','numbered_list_item','quote','code','toggle','callout'];
  for (const k of keys) {
    const b = j[k];
    if (b && Array.isArray(b.rich_text)) {
      return b.rich_text.map(function (t) { return t.plain_text || ''; }).join('');
    }
  }
  if (Array.isArray(j.rich_text)) {
    return j.rich_text.map(function (t) { return t.plain_text || ''; }).join('');
  }
  return '';
}
const cv_md = $input.all().map(function (i) { return blockText(i.json); }).filter(Boolean).join('\n');
const prev = $('Parse Clean MD').first().json;
return [{ json: { url: prev.url, clean_md: prev.clean_md, cv_md: cv_md } }];

