function cap(s) {
  s = String(s || '');
  return s.length <= 1900 ? s : s.slice(0, 1899) + '\u2026';
}
function asText(value) {
  if (value == null) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) {
    return value.map(function (x) { return '- ' + x; }).join('\n\n');
  }
  return String(value);
}
function repairJson(s) {
  let out = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < s.length; i++) {
    const c = s[i];
    const code = s.charCodeAt(i);
    if (!inString) {
      if (c === '"') inString = true;
      out += c;
      continue;
    }
    if (escaped) {
      out += c;
      escaped = false;
      continue;
    }
    if (c === '\\') {
      out += c;
      escaped = true;
      continue;
    }
    if (c === '"') {
      out += c;
      inString = false;
      continue;
    }
    if (code < 32) {
      if (c === '\n') out += '\\n';
      else if (c === '\r') out += '\\r';
      else if (c === '\t') out += '\\t';
      else out += '\\u' + ('0000' + code.toString(16)).slice(-4);
      continue;
    }
    out += c;
  }
  return out;
}
